"""Configuration for atlaslane."""

from celery.schedules import crontab

DATABASE_URL = "sqlite:///./atlaslane.db"
PAGE_SIZE = 50
SESSION_COOKIE_NAME = "atlaslane_session"
MAX_UPLOAD_BYTES = 5 * 1024 * 1024
AWS_REGION = "eu-central-1"

CELERYBEAT_SCHEDULE = {
    "purge-closed-accounts": {
        "task": "jobs.purge.purge_closed_accounts",
        "schedule": crontab(minute="0", hour="4"),
    },
}

"""HTTP routes for the profile area.

One function per route. The application object in app.py imports this module
and registers each of them.
"""

from models import User, Invoice


def get_profile(session, user_id):
    user = session.get(User, user_id)
    return {"email": user.email, "full_name": user.full_name}


def list_invoices(session, user_id):
    invoice = session.query(Invoice).filter(Invoice.user_id == user_id).first()
    return {"billing_name": invoice.billing_name, "reference": invoice.reference}

"""Small string helpers. No personal data passes through this module."""


def slugify(value):
    return "-".join(part for part in value.lower().split() if part)


def truncate(value, limit=80):
    if len(value) <= limit:
        return value
    return value[: limit - 3] + "..."


def humanise_bytes(count):
    for unit in ("B", "KB", "MB"):
        if count < 1024:
            return f"{count} {unit}"
        count //= 1024
    return f"{count} GB"
